ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_any_19"] = {
{"s2_routine_tap_quit_003","any",2,"reg=civilian,family|tmp=fresh,seasoned|day=15,60",{1,"Tap quit on a Thursday, I circled it on the feed store calendar, right under the power",2,"Why would you write that down?",1,"Somebody's gotta keep the minutes",2,"Then write down that I said this is the worst club I ever joined"}},
{"s2_routine_gin_rummy_004","any",3,"reg=civilian,family|tmp=seasoned|day=15,400|hour=18,23",{1,"Gin",2,"That's six in a row, either you're cheating or the Lord's making something up to you",1,"Deal again",3,"Deck's been missing the jack of clubs since Muldraugh, you know",2,"Well, that explains a whole lot about my week"}},
{"s2_routine_porch_thermometer_005","any",2,"reg=civilian,family|tmp=seasoned|day=15,75|hour=11,17|world=window,building",{1,"Ninety-four on the porch thermometer, and that's in the shade",2,"Don't say numbers, numbers make it hotter",1,"Remember the window unit at the discount store? I'd stand in front of it every payday",2,"I said don't"}},
{"s2_routine_chicory_006","any",2,"reg=civilian,family|tmp=seasoned|day=30,160",{1,"I've boiled these grounds four times, it's brown water with a memory",2,"Chicory grows wild in the ditch past the church, folks used to roast the roots",1,"Used to meaning when?",2,"Meaning when my great-granny got mad at the price of coffee",1,"Well, I'm mad at the price of coffee - show me the ditch"}},
{"s2_routine_clothesline_007","any",3,"reg=civilian,family|tmp=seasoned|day=15,400",{1,"Clothesline's strung between the shed and the maple - don't walk into it at night",2,"Who's walking around the yard at night?",1,"You, every night about two, to pee off the back step - I hear you",3,"Got you there"}},
{"s2_routine_freezer_roast_008","any",2,"reg=civilian,family|tmp=seasoned|day=15,50|hour=16,5|world=generator",{1,"Generator's got maybe nine hours of gas, I say we run the freezer and nothing else",2,"Freezer's got one roast and forty pounds of ice we can't use",1,"Then we cook the roast tonight and shut it off for good",2,"It's froze solid",1,"Then tomorrow we eat it, I ain't letting that roast rot in a dead freezer"}},
{"s2_routine_squash_bugs_009","any",2,"reg=civilian,family|tmp=seasoned|day=30,110",{1,"Squash bugs got the zucchini, every leaf looks like a doily",2,"Pick 'em off into a can of soapy water, mamaw did that forty years",1,"Did it work for Mamaw?",2,"No, but it gave her something to do with her hands"}},
{"s2_routine_mason_jars_010","any",3,"reg=civilian,family|tmp=seasoned|day=40,140|world=building",{1,"Found two cases of Mason jars in the church basement - lids and rings too, nobody took 'em",2,"Course nobody took 'em, everybody took the guns and the beer",3,"We got beans coming in and no pressure canner",1,"Water bath the tomatoes, pickle the beans, I'm not losing one jar to botulism",2,"Listen at this, home economics champion of Knox County"}},
{"s2_routine_rooster_011","any",2,"reg=civilian,family|tmp=seasoned|day=20,400|hour=4,9",{1,"Rooster started in at four-fifteen again",2,"I know, I was there",1,"Every one of those things between here and Ekron heard that bird",2,"You want to tell the kids we're having Reverend for supper? Be my guest"}},
{"s2_routine_bath_order_012","any",2,"reg=family|tmp=seasoned|day=15,400|world=vehicle",{1,"Saturday's bath night - warm water goes kids first, then whoever's least dirty",2,"So I go last, every single week",1,"You go last because you come back from runs smelling like the inside of a truck stop",2,"That's honest work you're smelling"}},
{"s2_routine_mint_neck_013","any",2,"reg=civilian,family|tmp=seasoned|day=15,90|hour=17,22|world=water",{1,"Mosquitoes down by the creek are big enough to show up on a scanner",2,"Rub the mint on your neck, it grows by the downspout",1,"I smell like a stick of gum and they're still biting",2,"Then they like you, and somebody should"}},
{"s2_routine_watch_swap_014","any",3,"reg=civilian,family|tmp=seasoned|day=15,400|hour=19,23",{1,"Who's got two to four?",2,"Not me, I had it Tuesday and Thursday both",3,"I'll take it if somebody does my dishes",1,"Deal, wake Wade up at four and don't let him roll back over",3,"He sleeps like the dead - sorry, he sleeps real heavy"}},
{"s2_routine_hand_pump_015","any",2,"reg=civilian,family|tmp=seasoned|day=20,400",{1,"Old hand pump at the Pruitt place still draws, took twenty minutes to prime it",2,"Water tastes like pennies",1,"Tastes like pennies and it's free, I'd marry that pump"}},
{"s2_routine_weevils_016","any",3,"reg=civilian,family|tmp=seasoned|day=40,400",{1,"Flour's got weevils",2,"Sift 'em out",1,"I sifted, it's more weevil than flour now",3,"Protein, bake it and don't tell anybody what's in it",2,"You just told everybody"}},
{"s2_routine_green_tomatoes_017","any",2,"reg=civilian,family|tmp=seasoned|day=95,130|hour=5,11|world=vehicle,snow",{1,"Frost on the windshield this morning - first one",2,"Pull the last green tomatoes and wrap 'em in newspaper - they'll ripen in the dark",1,"Newspaper's from the tenth of July, front page is all about the flooding out west",2,"Good, the tomatoes will have something to read"}},
{"s2_routine_split_rail_018","any",2,"reg=civilian,family|tmp=seasoned|day=90,180|world=fence",{1,"We need four cords before Christmas and we got maybe one",2,"There's split-rail fence around the horse farm off Rosewood Road - dry, and already cut to length",1,"Burning a man's fence feels like quitting",2,"Freezing to death feels like quitting worse"}},
{"s2_routine_katydids_019","any",2,"reg=civilian,family|tmp=seasoned|day=25,75|hour=21,2|mood=calm|world=road",{1,"Hear that? Katydids",2,"Used to be you couldn't hear 'em over the highway",1,"Used to be a lot of things",2,"Don't start, just listen to the bugs"}},
{"s2_routine_compound_bow_020","any",2,"reg=civilian,family|tmp=seasoned|day=115,165|world=water,trees",{1,"Deer are moving - Doe and two yearlings at the tree line behind the water tower",2,"Rifle's loud, everything between here and the river hears it",1,"Bow, then - Mitch had a compound hanging in his garage",2,"Mitch couldn't hit a barn with that bow",1,"Mitch isn't the one shooting it"}},
{"s2_routine_wool_sock_021","any",2,"reg=civilian,family|tmp=seasoned|day=100,260|mood=funny",{1,"Anybody seen my other wool sock?",2,"Dog had one",1,"We don't have a dog",2,"Then something had one, and I'm not going out there to ask it"}},
{"s2_routine_am_dial_022","any",2,"reg=civilian,family|tmp=seasoned|day=15,400|hour=19,23",{1,"Anything?",2,"Just the hum, went all the way down the AM dial twice",1,"Leave it on low anyway",2,"Batteries",1,"I know - leave it on low"}},
{"s2_routine_parsonage_bees_023","any",3,"reg=civilian,family|tmp=seasoned|day=20,120|world=building,road",{1,"Bees built in the wall of the old Baptist parsonage - you can hear 'em humming from the sidewalk",2,"You're not getting stung over honey",1,"I got stung for a lot less before all this - six-fifty an hour at the lumberyard",3,"Smoke 'em first, burlap in a coffee can - my uncle kept hives"}},
{"s2_routine_phone_book_024","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=funny",{1,"We're down to the phone book in the outhouse",2,"Which part?",1,"Halfway through the S's, goodbye to all the Smiths",2,"Leave the plumbers alone, out of respect"}},
{"s2_routine_fabric_scissors_025","any",2,"reg=civilian,family|tmp=seasoned|day=30,400",{1,"Hold still or you're getting a boot camp cut whether you like it or not",2,"I am holding still, your hands are shaking",1,"They're not shaking, it's the scissors, these are fabric scissors",2,"Great, wonderful - go ahead"}},
{"s2_routine_chore_chart_026","any",2,"reg=family|tmp=seasoned|day=20,400|mood=sad",{1,"Who took Jesse's name off the chore chart?",2,"I did, didn't seem right to leave it up",1,"He had the chickens this week",2,"I'll do the chickens"}},
{"s2_routine_heat_lightning_027","any",3,"reg=civilian,family|tmp=seasoned|day=15,80|hour=20,23|world=rain,storm",{1,"Heat lightning over toward Brandenburg",2,"No rain in it, there never is",3,"Put the barrels out anyway",2,"They're out, they've been out since July"}},
{"s2_routine_mystery_cans_028","any",3,"reg=civilian,family|tmp=seasoned|day=20,400|world=building,water",{1,"Tallied the pantry, seventy-one cans, nine with no labels",2,"Mystery cans, best part of my week",1,"Two are dented bad, those get opened first",3,"Swollen ones go in the creek - don't taste 'em to check",2,"I tasted one to check - one time",3,"I know, I held the bucket all night"}},
{"s2_routine_coons_corn_029","any",2,"reg=civilian,family|tmp=seasoned|day=35,90",{1,"Coons got in the sweet corn last night, stripped four rows clean",2,"We shoot coons now?",1,"We eat coons now",2,"Well, somebody's papaw is smiling somewhere"}},
{"s2_routine_two_candles_030","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|hour=19,23",{1,"Two candles, not three, we're down to half a shoebox",2,"I can't read by two",1,"Then don't read, talk to us",2,"That's why I was reading"}},
{"s2_routine_tobacco_uncut_031","any",2,"reg=civilian,family|tmp=seasoned|day=45,85",{1,"Burley's still standing in the Merritt field, nobody cut it",2,"First year in a hundred that field's not hanging in the barn by now",1,"Smell of that barn in September - you remember it?",2,"I remember hating it"}},
{"s2_routine_blackberries_032","any",2,"reg=civilian,family|tmp=seasoned|day=15,35",{1,"Blackberries along the rail line are dead ripe - look at my hands",2,"You watch for copperheads in them brambles?",1,"I watched for everything, snakes are the least of it",2,"Snakes are still on the list"}},
{"s2_routine_pawpaws_033","any",2,"reg=civilian,family|tmp=seasoned|day=60,90|world=water",{1,"Pawpaws in the creek bottom are dropping",2,"Tastes like a banana that went off to college",1,"They won't keep, two days and they're mush",2,"Then we eat 'em all today and feel sick together"}},
{"s2_routine_walnut_hulls_034","any",2,"reg=civilian,family|tmp=seasoned|day=90,125|world=vehicle",{1,"Black walnuts all over the yard - hands stained for a week",2,"Lay 'em in the drive and run the truck over - knocks the hulls right off",1,"Truck's on a quarter tank",2,"Then stomp 'em - wear the old boots"}},
{"s2_routine_plywood_door_035","any",2,"reg=family|tmp=seasoned|day=15,400|mood=funny|world=door",{1,"Boots off at the door!",2,"There's no door - there's plywood",1,"Then boots off at the plywood!"}},
{"s2_routine_lye_soap_036","any",3,"reg=civilian,family|tmp=seasoned|day=60,400",{1,"Lye soap's done, it sat six weeks",2,"Smells like a burned hog",1,"It's clean - clean doesn't have to smell nice",3,"My mother would've fainted, us washing our hair with that",1,"Your mother would've made it better",3,"She would have"}},
{"s2_routine_tin_roof_037","any",2,"reg=civilian,family|tmp=seasoned|day=15,400|mood=calm|world=building,rain",{1,"Rain on a tin roof, best sound in the county",2,"I catch myself listening to it instead of what's outside",1,"Why'd you have to go and say that?",2,"Because I'm on watch in an hour"}},
{"s2_routine_propane_slosh_038","any",2,"reg=civilian,family|tmp=seasoned|day=30,400",{1,"Last propane tank's got that sloshing sound",2,"Cook the beans on the woodstove",1,"Beans take four hours on the woodstove",2,"Good thing hours are the one thing we got plenty of"}},
{"s2_routine_boot_sole_039","any",2,"reg=civilian,family|tmp=seasoned|day=20,400|world=water",{1,"Sole came off my boot on the Irvington run",2,"Shoe glue's in the red toolbox",1,"I used it all on your boot",2,"Duct tape, then, wrap it twice and stay out of the creek"}},
{"s2_routine_smokehouse_040","any",2,"reg=civilian,family|tmp=seasoned|day=110,250",{1,"Smokehouse at the Abner farm still draws, hung the venison in there Thursday",2,"You board up the vent? Smoke carries",1,"Smell carries farther than smoke, and I can't board a smell",2,"Then take the rifle every time you go check it"}},
{"s2_routine_keeping_date_041","any",2,"reg=civilian,family|tmp=seasoned|day=62,400",{1,"What's today?",2,"{date}, or near it - I lost a day in August when I had the fever",1,"So it's maybe {date}",2,"It's {date} because I say so, somebody has to say so"}},
{"s2_routine_melted_candy_042","any",2,"reg=civilian,family|tmp=seasoned|day=20,120|mood=funny",{1,"Found a candy bar melted flat under the seat of that station wagon",2,"Did you eat it?",1,"I licked it off the wrapper like a hound",2,"And you didn't bring any back",1,"Nothing to bring back, that's the story, start to finish"}},
{"s2_routine_salt_block_043","any",2,"reg=civilian,family|tmp=seasoned|day=60,400",{1,"We're low on salt, that's a real problem, not me griping",2,"Feed store at the Ekron crossroads had mineral blocks for cattle",1,"You want me to lick a cow block?",2,"Scrape it, nobody said lick"}},
{"s2_routine_lockup_044","any",2,"reg=civilian,family|tmp=seasoned|day=15,400|hour=20,23|world=door,window,building",{1,"Back door",2,"Barred",1,"Cellar hatch",2,"Chained - front's nailed, windows are boarded, same as last night",1,"Same as last night is the whole point"}},
{"s2_routine_cistern_possum_045","any",3,"reg=civilian,family|tmp=seasoned|day=20,400|world=water,rain",{1,"There's a dead possum in the cistern",2,"How long?",1,"Long enough",2,"Then we haul from the creek till it rains",3,"I'll bail it out, somebody find me a clothespin for my nose"}},
{"s2_routine_sticky_sheets_046","any",2,"reg=civilian,family|tmp=seasoned|day=15,60|hour=22,3",{1,"Can't sleep, sheets keep sticking to me",2,"Sleep on the floor - floor's cooler",1,"Floor's got spiders",2,"Spiders are cooler too"}},
{"s2_routine_one_pumpkin_047","any",2,"reg=family|tmp=seasoned|day=90,112|world=window",{1,"Pumpkins came in - seven",2,"Kids want to carve one",1,"Carving wastes food",2,"One, roast the seeds - let 'em carve one",1,"One, and no candle in it, nothing lit in a window"}},
{"s2_routine_hereford_048","any",3,"reg=civilian,family|tmp=seasoned|day=20,200",{1,"There's a Hereford standing in the middle of Dixie Highway like she paid for it",2,"She might have, nobody else is using it",3,"That's a thousand pounds of beef and no freezer",1,"So we leave her be",3,"So we leave her be - for now"}},
{"s2_routine_chicken_wire_049","any",2,"reg=civilian,family|tmp=seasoned|day=20,400|mood=angry",{1,"Rabbits got under the chicken wire again",2,"Bury it a foot down, I told you a foot",1,"You told me six inches",2,"I told you a foot, and you heard six inches because you were tired"}},
{"s2_routine_skillet_cornbread_050","any",3,"reg=civilian,family|tmp=seasoned|day=20,400|mood=warm",{1,"Cornbread in the skillet - real cornbread",2,"With what eggs?",1,"Miss Henrietta gave up two - don't ask how I got 'em out from under her",3,"Your wrist is bleeding",1,"That's how"}},
{"s2_routine_spotted_dog_051","any",2,"reg=civilian,family|tmp=seasoned|day=15,400",{1,"That spotted dog's back at the edge of the yard",2,"Don't feed it",1,"I didn't feed it",2,"Then why's it looking at you like you did?",1,"Half a biscuit - maybe"}},
{"s2_routine_glass_of_ice_052","any",2,"reg=civilian,family|tmp=seasoned|day=15,110|mood=funny|world=vehicle",{1,"Know what I'd trade the truck for? A glass of ice - just ice",2,"You'd trade a running truck for frozen water",1,"Clinking, in a glass - on a coaster",2,"Now you want a coaster"}},
{"s2_routine_quit_shaving_053","any",2,"reg=civilian,family|tmp=seasoned|sex=m|day=40,400",{1,"Quit shaving, water's too dear for it",2,"You look like the fella that used to sleep behind the feed mill",1,"Fella behind the feed mill had it all figured out, turns out"}},
{"s2_routine_stovepipe_054","any",3,"reg=civilian,family|tmp=seasoned|day=60,125|world=window,building,winter",{1,"Winter's coming, ready or not, I want the back room sealed and the woodstove in the living room",2,"Pipe out through the window?",1,"Through the window, sheet metal around it - Carol at the hardware showed me how once",3,"Does Carol's hardware still have sheet metal?",1,"One way to find out"}},
{"s2_routine_ten_speed_055","any",2,"reg=civilian,family|tmp=seasoned|day=20,400|world=vehicle",{1,"Fixed the chain on that ten-speed, quieter than the truck, and it don't drink",2,"It's also slower than every zombie in Riverside",1,"Not downhill it ain't"}},
{"s2_routine_count_off_056","any",3,"reg=civilian,family|tmp=fresh,seasoned|day=15,45|hour=5,8|world=trees",{1,"Count off",2,"Here",3,"Here - Ugh",1,"Where's Denny?",2,"Latrine - he's fine, you can quit staring at the woods like that"}},
{"s2_routine_squirrel_dumplings_057","any",2,"reg=civilian,family|tmp=seasoned|day=40,400",{1,"Squirrel and dumplings",2,"Squirrel and flour paste",1,"You want to cook? Pot's right there",2,"No, no, it's real good - squirrel and dumplings"}},
{"s2_routine_i_spy_058","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=funny",{1,"I spy with my little eye something boarded up",2,"Everything",1,"Correct - your turn",2,"I'm not playing this anymore"}},
{"s2_routine_declared_sunday_059","any",2,"reg=civilian,family|tmp=seasoned|day=20,400",{1,"Is it Sunday?",2,"It's {weekday}",1,"Close enough - I'm resting",2,"You can't declare it Sunday because your back hurts"}},
{"s2_routine_bleach_drops_060","any",2,"reg=civilian,family|tmp=fresh,seasoned|day=15,60",{1,"Don't give me a bleach recipe you heard from somebody. This is drinking water",2,"I only asked if it would work",1,"I don't know. That's my whole point; let's not gamble on it"}},
{"s2_routine_pepper_seed_061","any",2,"reg=civilian,family|tmp=seasoned|day=60,130",{1,"Save seed off the best pepper plant, not the biggest pepper - there's a difference",2,"What's the difference?",1,"Biggest pepper might be on a sick plant, best plant gives good peppers next year",2,"Next year, you say that like it's a sure thing",1,"I say it like I'm planting peppers"}},
{"s2_routine_lightning_bug_jar_062","any",2,"reg=family|tmp=seasoned|day=15,32|hour=20,22|mood=warm|world=storm",{1,"Look at the kids out there with the jar",2,"Tell 'em to let the lightning bugs go before bed",1,"I told 'em - Emmy asked if the bugs got a mama waiting on 'em",2,"What'd you say?",1,"Said yes, said everybody does"}},
{"s2_routine_poker_chores_063","any",4,"reg=civilian,family|tmp=seasoned|day=20,400|hour=18,23|mood=funny",{1,"I'll see your latrine duty and raise you a week of dishes",2,"Fold",3,"Call",4,"All in, every chore I got",1,"You got no chores, you're on watch",4,"Then I'm all in on watch, somebody take it off me"}},
{"s2_routine_kerosene_lamp_064","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|hour=18,23",{1,"Trim the wick before you light that lamp, it's smoking the chimney black",2,"Since when do you know about lamps?",1,"Since Grandma's house had no power till 1961 and she made me clean every chimney",2,"Then you clean it"}},
{"s2_routine_outhouse_dig_065","any",3,"reg=civilian,family|tmp=seasoned|day=25,400",{1,"Time to dig a new hole for the outhouse",2,"I dug the last one",3,"I dug the one before that",1,"Then it's my turn, nobody say a word about it being my turn",2,"Wasn't gonna, I was gonna say thank you"}},
{"s3_c01_drill_moulage_001","any",3,"reg=rescue|role=rescue_medical,rescue_firefighter|day=2,90|mood=funny|world=vehicle",{1,"Remember the mass casualty drill at the fairgrounds in April? School bus rollover, fake blood, the works",2,"Drama club kids played the victims",3,"One boy played dead so well he fell asleep on the grass",1,"We tagged him black and he snored through the whole debrief",3,"Tall kid - braces, I hope he's still that good at lying still"}},
{"s3_c01_arms_first_002","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|day=3,200|mood=calm|world=road",{1,"Run it for me, somebody's down in the road - what's first?",2,"Scene safety - then airway",1,"Wrong, arms and ankles first, before I even kneel down",2,"That's not how the book has it",1,"I'm the book now - write it in the margin"}},
{"s3_c01_tape_ankle_003","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|tmp=seasoned,veteran|day=2,200|mood=grim",{1,"We ran out of black tags the second day",2,"What'd you use?",1,"Electrical tape, around the wrist for dead - around the ankle for bit",2,"Why the ankle?",1,"So whoever comes along later knows which end to watch"}},
{"s3_c01_tones_habit_004","any",3,"reg=rescue|role=rescue_firefighter|day=3,90|hour=4,11|mood=sad|world=vehicle,generator",{1,"Station tones went off at two this morning, generator hiccup, I figure",2,"I had my boots on before I was awake",3,"All three of us did, standing at the engine with our coats half on",1,"Nobody said a word, we just hung the coats back up on the pegs"}},
{"s3_c01_hydrant_pressure_005","any",2,"reg=rescue|role=rescue_firefighter|day=2,40|mood=calm",{1,"Hydrant on Main is down to a dribble",2,"Water tower's draining, nobody's running the pumps",1,"Somebody is, pressure came back for about an hour on Tuesday",2,"Then somebody's still out at the water plant turning valves by hand",1,"Somebody ought to go take that person a sandwich"}},
{"s3_c01_parsonage_burn_006","any",3,"reg=rescue|role=rescue_firefighter|day=2,120|mood=grim|world=building",{1,"The parsonage on {street} burned all night, we stood in the church lot and watched it go",2,"Pumper's loud, it would've pulled every one of them for a mile",3,"So we wet down the Hensley roof next door with buckets out of the baptistry",1,"Hensleys still have a roof, that's what goes in my report"}},
{"s3_c01_call_lights_007","any",2,"reg=rescue|role=rescue_medical|day=1,60|mood=sad|world=generator",{1,"Every call light on the third floor was lit when we went out the back",2,"Generator does that when it switches over, lights them all up",1,"You worked that floor nine years - you ever once see it do that?",2,"Pass me the tape"}},
{"s3_c01_opal_grill_008","any",2,"reg=rescue|role=rescue_medical|day=1,90|mood=sad",{1,"Miss Opal from the cafeteria kept the flat-top going till the gas quit",2,"Grilled cheese for anybody in scrubs, I ate three standing up",1,"Did she get out?",2,"Last I saw, she was making another one, cutting it corner to corner, like always"}},
{"s3_c01_roscoe_tunnel_009","any",3,"reg=rescue|role=rescue_medical|mood=warm|world=door",{1,"Only man with a key to every door in that building was Roscoe on night housekeeping",2,"Roscoe walked us out through the steam tunnel to the parking deck",3,"He knew that tunnel because he snuck cigarettes down there for twenty years",1,"Twenty years of write-ups for smoking, eleven people breathing",2,"First store we find with a carton, that carton is Roscoe's"}},
{"s3_c01_blood_cooler_010","any",2,"reg=rescue|role=rescue_medical|day=3,60|mood=grim",{1,"I carried the O negative out in a lunch cooler with a cartoon dog on the lid",2,"How many units?",1,"Nine, seven went into people - two cooked in a Sunday school room with no ice",2,"Seven's good, seven is seven people"}},
{"s3_c01_hold_breath_011","any",2,"reg=rescue|role=rescue_medical|mood=funny",{1,"I had a man on the X-ray table when the code came over - told him take a deep breath and hold it",2,"What'd he do?",1,"Held it, and I ran - I never did tell him he could breathe",2,"Well, he's probably still holding it"}},
{"s3_c01_last_normal_run_012","any",1,"reg=rescue|role=rescue_medical,rescue_firefighter|day=3,200|mood=sad",{1,"Last normal run I made was chest pain on Dixie Highway - sixty-year-old man, sweaty, scared",1,"Aspirin, oxygen, nitro under the tongue, signed him over at one-fourteen in the morning",1,"Normal, I keep going back over it like there's something hid in it"}},
{"s3_c01_chief_complaint_013","any",2,"reg=rescue|role=rescue_medical|day=3,200|mood=funny",{1,"Found an old run sheet in my jacket, lady on Thursday night - chief complaint, anxiety",2,"Anxiety",1,"Said she felt like something awful was about to happen - we gave her a paper bag to breathe in",2,"Cross it out, chief complaint, correct"}},
{"s3_c01_collar_guard_014","any",1,"reg=rescue|role=rescue_medical,rescue_firefighter|day=5,300|mood=calm",{1,"Six cervical collars, nobody out here gets a neck injury worth a collar anymore",1,"Wrap one around a forearm, though - Velcro holds, hard plastic, too",1,"Huh - well, that's six arm guards, then"}},
{"s3_c01_ratio_sign_015","any",2,"reg=rescue|role=rescue_medical|day=5,300|mood=funny",{1,"Remember when we were going to walk out over staffing? Five nurses for forty beds?",2,"I made a picket sign, it had glitter on it",1,"Now it's the two of us and eleven cots",2,"Best ratio I ever worked, nobody mentioned what came with it"}},
{"s3_c01_her_first_016","any",2,"reg=rescue|role=rescue_medical|mood=warm",{1,"Fella came in with a hole in his thigh I could've put my thumb in",2,"Bleeding bad?",1,"Wouldn't let me near it, kept pointing at his wife, her first, he says, her wrist hurts",2,"So what'd you do with him?",1,"Wrapped her wrist first, took forty seconds, he watched every one of them like a clock"}},
{"s3_c01_brandenburg_74_017","any",2,"reg=rescue|role=rescue_firefighter|tmp=veteran,seasoned|day=2,120|mood=grim|world=door",{1,"We did this after the Brandenburg tornado in seventy-four, house to house, paint on the door",2,"What'd you paint?",1,"The date, and a number for how many inside - back then the number meant bodies",2,"What's it mean now?",1,"Same, you just knock different before you go in"}},
{"s3_c01_siren_thumb_018","any",1,"reg=rescue|role=rescue_medical,rescue_firefighter|day=4,120|mood=calm|world=road",{1,"Every intersection, my thumb goes looking for the siren switch",1,"Haven't touched it since Friday night, thumb didn't get the memo",1,"Taped a bottle cap over it, now it's got something to argue with"}},
{"s3_c01_gloves_small_019","any",2,"reg=rescue|role=rescue_medical|day=7,300|mood=funny",{1,"Last box of exam gloves in the county, and it's size small",2,"My hands are a large",1,"Your hands are a small now - squeeze"}},
{"s3_c01_dig_deep_020","any",2,"reg=rescue|role=rescue_firefighter|tmp=seasoned|day=4,300|mood=grim|world=fence",{1,"People think burning a body is quick, takes most of a cord of wood to do one right",2,"We don't have a cord of wood",1,"We've got the backhoe the county left parked at the ball field",2,"Then we dig - deep, the way Daddy set fence posts, past where the dogs could get to"}},
{"s3_c01_triage_officer_021","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|day=1,30|mood=funny",{1,"That Guard medic kept asking me where the triage officer was",2,"It was you",1,"I know it was me, I kept looking over my shoulder for somebody better"}},
{"s3_c01_odometer_022","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|day=5,300|hour=4,11|mood=warm|world=vehicle",{1,"Box 7 rolled over two hundred and twelve thousand miles this morning",2,"Where at?",1,"Right in front of the feed store, I tapped the horn - real quiet",2,"That rig's going to outlive the whole ambulance service",1,"She already has"}},
{"s3_c01_pancake_plates_023","any",3,"reg=rescue|role=rescue_firefighter|mood=funny|world=building",{1,"Found four hundred paper plates in the station closet, left over from the pancake breakfast",2,"That's four hundred meals",3,"If you find four hundred pancakes",1,"I'm just saying the plates are handled, plates were always the hard part"}},
{"s3_c01_maggots_024","any",2,"reg=rescue|role=rescue_medical|day=10,300|mood=funny",{1,"Don't you pick those out of his leg",2,"They're maggots!",1,"They only eat what's already dead - Surgeons in the Civil War worked that out",2,"I would like to go back to not knowing that"}},
{"s3_c01_dixie_baby_025","any",3,"reg=rescue|role=rescue_medical,rescue_firefighter|day=3,200|mood=warm|world=window,road",{1,"Baby girl born in the back of Box 9 the third night - parked in the ditch on 31W",2,"What'd they name her?",3,"Her mama looked out the back window at the highway sign and said Dixie",1,"Dixie, seven pounds even - I weighed her on a fish scale"}},
{"s3_c01_sleeve_patch_026","any",2,"reg=rescue|role=rescue_medical|mood=calm",{1,"People see that patch on your sleeve and come running with every rash in the county",2,"Cut it off, then",1,"My daughter sewed that one on - crooked - it stays"}},
{"s3_c01_rig_door_names_027","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|day=5,300|mood=sad|world=door",{1,"I'm writing names on the inside of the rig door - everybody who was on shift Friday night",2,"How many so far?",1,"Thirty-one",2,"Leave some room at the bottom",1,"For who?",2,"The ones neither of us has remembered yet"}},
{"s3_c01_dayroom_recliner_028","any",2,"reg=rescue|role=rescue_firefighter|tmp=veteran,seasoned|mood=funny|world=door",{1,"Captain, there's three of them inside the station",2,"Where inside?",1,"Dayroom, one of them's sitting in your recliner",2,"Pull the bay door down and let him keep it - footrest was broke anyhow"}},
{"s3_c01_aerial_lookout_029","any",3,"reg=rescue|role=rescue_firefighter|day=3,90|hour=4,11|mood=calm|world=vehicle,stairs,building,water,fire",{1,"Ran the aerial up seventy feet this morning, you can see clean to the river",2,"See anything?",1,"Smoke over West Point, and somebody on a roof in Riverside waving a white towel",3,"Ladder truck's got a quarter tank",1,"Quarter tank gets us there - boots on"}},
{"s3_c01_noon_siren_030","any",4,"reg=rescue|role=rescue_firefighter|day=5,120|mood=grim|world=road,generator",{1,"Town siren, tested every Saturday noon for forty years, and every one of them can hear it",2,"You want to set it off?",1,"Once - pull them all to the station while the church bunch slips out the back road",3,"Siren needs power",4,"Generator's in the bay, I know where the switch is",2,"And who stays behind to throw it?",4,"I said I know where the switch is"}},
{"s3_c01_smoke_detectors_031","any",2,"reg=rescue|role=rescue_firefighter|day=10,150|mood=calm|world=door,road",{1,"Every smoke detector in town is dying at once, chirp, every forty seconds, up and down the street",2,"And it's pulling them right into the houses",1,"Somebody ought to go door to door and yank the batteries",2,"Nine-volts, we need nine-volts for the handhelds",1,"Well, now it's a supply run"}},
{"s3_c01_carry_water_032","any",3,"reg=rescue|role=rescue_medical|day=5,300|mood=angry",{1,"We treat the one who can carry water tomorrow, that's the only arithmetic left",2,"That's not medicine",1,"Then you tell me what it is",3,"It's the kind of thing you say out loud once, so you never have to say it again",2,"I'm doing the old lady first - write me up"}},
{"s3_c01_inhaler_puffs_033","any",2,"reg=rescue|role=rescue_medical|day=5,200|mood=fear",{1,"The Coomer boy's inhaler has maybe ten puffs in it",2,"Ten puffs is a week, if he's careful",1,"He's nine, he isn't careful with anything he owns",2,"Then I hold it, he comes and asks me, every single time"}},
{"s3_c01_blue_h_signs_034","any",2,"reg=rescue|day=3,60|hour=4,11|mood=sad|world=door",{1,"Folks are still following the blue H signs off 31W",2,"To the hospital?",1,"Station wagon in the ER circle this morning - doors open - Hazards still blinking, real faint",2,"Paint over the signs",1,"I've got one can, I'm starting with the one at the county line"}},
{"s3_c01_helipad_sleep_035","any",2,"reg=rescue|role=rescue_medical|day=0,21|mood=calm|world=window,building",{1,"Last helicopter off the roof took two patients and Dr. Haskins",2,"He'd been on for thirty hours straight",1,"He was asleep before it cleared the parking deck, I watched his head tip against the window",2,"Good, somebody got to sleep"}},
{"s3_c01_ems_mug_036","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|day=7,300|mood=funny",{1,"County gave us a coffee mug for EMS Week back in May - thanks for all you do, printed on the side",2,"Where's yours at?",1,"On the dash, it's where I keep the loose rounds",2,"Thanks for all you do"}},
{"s3_c01_kid_tape_037","any",2,"reg=rescue|role=rescue_medical|day=3,300|mood=sad",{1,"There's a color tape in the pediatric bag, lay it next to the child and it tells you the dose",2,"You had to use it yet?",1,"Twice, both times I rolled it back up without reading the color out loud"}},
{"s3_c01_shaking_hands_038","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|day=7,300|mood=warm|world=vehicle",{1,"Your hands are shaking",2,"Low on sugar - it's nothing",1,"Sit down on that bumper and eat half of this",2,"That's your half",1,"It was - eat"}},
{"s3_c01_response_time_039","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|day=7,300|mood=funny",{1,"County average response time used to be eleven minutes, we got a plaque for it",2,"What is it now?",1,"Depends how fast you can walk to us"}},
{"s3_c01_rig_bedroom_040","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|hour=20,4|mood=calm|world=door",{1,"You sleeping in the rig again?",2,"Doors lock, it's got a cot, and the back stays cooler than the house",1,"It smells like bleach and old boots in there",2,"Smells like work, I sleep better when it smells like work"}},
{"s3_c01_phone_tree_041","any",2,"reg=rescue|role=rescue_firefighter|day=5,200|hour=20,23|mood=sad|world=trees",{1,"Volunteer phone tree, I'm number six - six calls seven",2,"Who's seven?",1,"Harlan Goins, I try him on the CB every night at nine",2,"Answer yet?",1,"Not yet, I'm still six, though"}},
{"s3_c01_turnout_heat_042","any",2,"reg=rescue|role=rescue_firefighter|hour=11,18|mood=funny",{1,"Turnout coat stops teeth, I've seen it happen",2,"It also cooks you, it's ninety-six in the shade",1,"So I get to pick between bit and baked",2,"Pick baked, somebody can pour water on baked"}},
{"s3_c01_curtain_bays_043","any",3,"reg=rescue|role=rescue_medical|day=1,40|mood=fear|world=building",{1,"Friday night we put the bitten in the left bays and everybody else on the right",2,"Curtain down the middle",3,"A curtain, like that was a wall",1,"Around two in the morning, a lady on the right side asked could we pull it a little tighter"}},
{"s3_c01_ceiling_tech_044","any",2,"reg=rescue|role=rescue_medical|day=2,120|mood=warm|world=building",{1,"Pharmacy tech hid up in the drop ceiling over the med room for two days",2,"Those tiles won't hold a cat",1,"She lay across the pipes, came down when she heard us calling Nadine, Nadine, like calling a dog in",2,"She tell you that?",1,"First thing out of her mouth, then she hugged me so hard my badge cracked"}},
{"s3_c01_belt_tourniquet_045","any",2,"reg=rescue|role=rescue_firefighter,rescue_medical|tmp=seasoned,veteran|mood=calm",{1,"Arm's pumping blood, you've got nothing but your belt - go",2,"Belt above the wound, stick through the loop, twist till it quits",1,"Good, and after?",2,"Then I write the time on his forehead",1,"Write it with what?",2,"Lipstick, ink, his own blood, whatever's in reach - somebody has to know how long it's been on"}},
{"s3_c01_fireworks_tent_046","any",2,"reg=rescue|role=rescue_medical|day=2,60|mood=sad|world=vehicle",{1,"I worked the first aid tent at the fireworks in West Point on the Fourth",2,"Busy?",1,"Two bee stings, one burned thumb, and a boy who ate a whole funnel cake and threw it back up",2,"Sounds like a real bad night",1,"Worst one I had all summer, I told my husband - he laughed at me in the car"}},
{"s3_c01_hold_the_light_047","any",2,"reg=rescue|role=rescue_medical|day=1,120|hour=19,5|mood=warm|world=building,inside",{1,"I can't do stitches, I can't do anything in here",2,"Can you hold a flashlight dead still for twenty minutes?",1,"I think so",2,"Then you're the most important person in this room - right there - don't you move it"}},
{"s3_c01_one_more_run_048","any",1,"reg=rescue|role=rescue_firefighter|tmp=veteran,seasoned|day=7,300|hour=21,4|mood=sad|world=vehicle",{1,"One more run, that's what I told Paula at supper Friday, one more run and I'm home",1,"She said she'd believe it when she saw the truck in the drive",1,"Still on that run, Paula, still on it"}},
{"s3_c01_worst_wrong_049","any",3,"reg=rescue|role=rescue_medical,rescue_firefighter|day=5,300|mood=grim|world=vehicle",{1,"Tell me the worst call you ever ran, before all this",2,"How come?",1,"Because I want to hear one where the bad part ended",3,"School bus and a grain truck, eighty-six, we had them all out in forty minutes",1,"All of them?",3,"All of them, two in helicopters - every one went home by Christmas"}},
{"s3_c01_lobby_piano_050","any",2,"reg=rescue|role=rescue_medical|day=2,90|mood=grim|world=vehicle,generator",{1,"Lobby music was still playing when we went back in for the suture trays",2,"Off the generator?",1,"Soft piano, and three of them standing in the gift shop in front of the get-well balloons",2,"You get the trays?",1,"Got the trays, hummed that piano thing all the way to the truck - still can't shake it"}},
{"s3_c02_dwayne_late_001","any",2,"reg=worker|role=worker|day=5,150|mood=sad",{1,"Twelve-hour shift at the water plant, started six o'clock Friday evening",2,"And nobody came to relieve you?",1,"Dwayne was on after me - Dwayne's late every time",2,"This is late, even for Dwayne",1,"I still leave the coffee can by his chair, he always forgets his"}},
{"s3_c02_chlorine_drums_002","any",3,"reg=worker|role=worker|day=7,150|mood=funny|world=water,road",{1,"Two drums of chlorine left, after that, what comes out of the tap is river with manners",2,"How long do two drums last?",1,"Couple of weeks, if nobody in town takes a bath",3,"Nobody in town has had a bath in a week - you can tell from the road"}},
{"s3_c02_hot_line_003","any",2,"reg=worker|role=worker|day=5,150|mood=calm|world=door,generator",{1,"Line out on Old 60 went hot yesterday, somebody's feeding a generator back into their house panel",2,"So somebody's got power",1,"Somebody's got power and never threw their main, anybody grabs that wire thinking it's dead, they're dead",2,"Nobody's climbing poles anymore",1,"Then I'll go knock on doors till I find them - hand me my gloves"}},
{"s3_c02_gaffs_sharp_004","any",2,"reg=worker|role=worker|day=5,300|mood=sad|world=vehicle",{1,"Lonnie's climbing gaffs are still in the bin on the bucket truck",2,"You going to use them?",1,"He sharpened those on his day off, out on his porch with a file and a beer - who does that?",2,"Lonnie did that",1,"Yeah, I'll keep them sharp"}},
{"s3_c02_plant_tripped_005","any",2,"reg=worker|role=worker|day=3,90|mood=calm|world=water",{1,"Power plant down on the river ran two whole days after the operators walked out",2,"By itself?",1,"Then something tripped, all of Knox went dark at six-twelve in the morning",2,"How do you know the minute?",1,"Microwave clock quit on me while I stood there waiting on a bowl of oatmeal"}},
{"s3_c02_aisle_four_006","any",3,"reg=worker|role=worker|day=9,300|mood=funny",{1,"Night stock crew locked ourselves in the grocery back room for nine days",2,"What'd you eat?",1,"Aisle four, crackers and baking goods",3,"Brown sugar off a spoon, cake mix stirred up with tap water",1,"If I never see another graham cracker, it'll still be too soon"}},
{"s3_c02_time_card_007","any",1,"reg=worker|role=worker|day=5,300|mood=sad",{1,"My time card's still in the rack at the plant - punched in Friday, ten fifty-eight at night",1,"Never punched out, far as the company knows, I'm still out on the floor",1,"Guess that's about right - I am"}},
{"s3_c02_fuel_math_008","any",2,"reg=worker|role=worker|tmp=seasoned,veteran|day=5,300|mood=calm|world=generator",{1,"Five thousand watt generator burns about half a gallon an hour at half load",2,"We've got eleven gallons",1,"Twenty-two hours of power - total - tell me what they're for",2,"Hot plate for the formula water, well pump, one hour a day",1,"And after that?",2,"After that we're pioneers"}},
{"s3_c02_block_box_009","any",2,"reg=worker|role=worker|hour=4,11|mood=calm|world=road",{1,"Stack cinder blocks around it three high - leave the top open so it can breathe",2,"That quiets it?",1,"Turns it from a lawnmower on this street into a lawnmower two streets over",2,"So two streets over gets them instead",1,"Two streets over is empty, I walked it this morning"}},
{"s3_c02_boarded_kitchen_010","any",2,"reg=worker|role=worker|day=3,90|mood=grim|world=door,window,building,generator",{1,"Family on {street}, generator running in the kitchen, every window boarded up tight",2,"Least they were safe from them",1,"Yeah, real safe, nothing got in",2,"Paint it on every door we pass, generator goes outside"}},
{"s3_c02_oil_change_011","any",2,"reg=worker|role=worker|day=5,300|mood=funny|world=generator",{1,"That generator's run a hundred and ten hours on the same oil",2,"And it's still running",1,"That's what my ex-husband said about his heart"}},
{"s3_c02_rickhouse_012","any",3,"reg=worker|role=worker|day=3,300|mood=funny",{1,"Rickhouse at the distillery's still full, barrels stacked seven high",2,"How much whiskey is that?",1,"Enough to clean every cut in this county for a hundred years",3,"Or enough for a fire they'd see from Indiana",2,"I vote cuts - mostly cuts"}},
{"s3_c02_dozer_ditch_013","any",2,"reg=worker|role=worker|day=1,40|mood=sad|world=vehicle,cars,window",{1,"Army boys couldn't run a dozer, they hollered for anybody from the county garage",2,"And you went",1,"Pushed cars off 31W into the ditch for eight hours",2,"Empty cars?",1,"Mostly - car seats, a birthday cake on a dashboard - I quit looking in the windows after a while"}},
{"s3_c02_salt_barn_014","any",3,"reg=worker|role=worker|hour=19,5|mood=funny|world=door,building,road",{1,"Salt barn at the county garage, round, one door, cool as a cellar",2,"We're sleeping on the road salt?",3,"Every breath in there smells like a pretzel",1,"Keeps the flies off, and nobody in history ever broke into a salt barn in July"}},
{"s3_c02_fuel_pump_lot_015","any",2,"reg=worker|role=worker|tmp=seasoned,veteran|day=7,300|mood=grim|world=vehicle",{1,"Box 9 needs a fuel pump",2,"From where?",1,"Same year pickup's sitting in the Methodist lot",2,"With the fella still in it?",1,"He's not using the fuel pump"}},
{"s3_c02_frozen_chicken_016","any",2,"reg=worker|role=worker|day=12,300|mood=funny",{1,"I was hauling forty thousand pounds of frozen chicken to Nashville",2,"Where's your rig?",1,"Weigh station on 31W - Reefer ran out of diesel on the eleventh day",2,"So that's the smell, I thought it was a whole crowd of them down there",1,"It's worse - it's chicken"}},
{"s3_c02_bus_route_017","any",2,"reg=worker|role=worker|day=7,200|mood=sad|world=building",{1,"I keep dreaming I drive my old bus route. All forty-one stops",2,"Even in a dream, I'd worry about who heard the horn",1,"I know what I'd be risking",2,"Then why?",1,"In case one of my kids was still waiting at the end of a driveway"}},
}
